CREATE TABLE settings (setting_key VARCHAR(50) PRIMARY KEY, setting_value JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin') NOT NULL DEFAULT 'customer', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email_digest CHAR(64) NOT NULL, ip_digest CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(email_digest,created_at), INDEX(ip_digest,created_at)) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED PRIMARY KEY, category VARCHAR(100) NOT NULL, name VARCHAR(200) NOT NULL, description TEXT NOT NULL, price_cents INT UNSIGNED NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, INDEX(category)) ENGINE=InnoDB;
CREATE TABLE delivery_areas (id VARCHAR(60) PRIMARY KEY, name VARCHAR(100) NOT NULL, fee_cents INT UNSIGNED NOT NULL, min_minutes INT UNSIGNED NOT NULL, max_minutes INT UNSIGNED NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, customer_name VARCHAR(120) NOT NULL, customer_phone VARCHAR(30) NOT NULL, fulfillment ENUM('delivery','pickup') NOT NULL, area_id VARCHAR(60) NULL, address VARCHAR(400) NULL, notes VARCHAR(1000) NOT NULL DEFAULT '', payment ENUM('pix','cash') NOT NULL, change_for_cents INT UNSIGNED NULL, payment_status ENUM('pending','confirmed') NOT NULL DEFAULT 'pending', status ENUM('received','preparing','ready','completed','cancelled') NOT NULL DEFAULT 'received', subtotal_cents INT UNSIGNED NOT NULL, fee_cents INT UNSIGNED NOT NULL, total_cents INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(area_id) REFERENCES delivery_areas(id), INDEX(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id INT UNSIGNED NULL, product_name VARCHAR(200) NOT NULL, unit_price_cents INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE order_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, event VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;